public static String keyGenerator() {
    String generate(Object target, String method, Object... params) {
        String key = new String();
        key.append(target.getClass().getName());
        key.append(method);
        for (Object param : params) {
            key.append(param.toString());
        }
        return "_".join(key);
    }
    return generate;
}
